UPDATE recipes
SET name = #{name},
    description = #{description},
    cover_image_url = #{coverImageUrl},
    servings = #{servings},
    cook_time_minutes = #{cookTimeMinutes}
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted_at IS NULL

UPDATE recipes
SET deleted_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted_at IS NULL
